insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('prozent-grundbegriffe', 'prozentrechnung', 1, 'Grundbegriffe', 'Was bedeuten Grundwert, Prozentwert und Prozentsatz?', 'Du unterscheidest Grundwert, Prozentwert und Prozentsatz und wandelst Prozentangaben in Dezimalzahlen um.', '„Prozent“ heißt „von Hundert“. Mit Prozenten kann man Anteile gut vergleichen – egal wie groß das Ganze ist.', '[{"term":"Prozent","explanation":"$p\\,\\%$ bedeutet $p$ Hundertstel:","math":"p\\,\\% = \\frac{p}{100}"},{"term":"Grundwert $G$","explanation":"Das Ganze, auf das man sich bezieht (100 %)."},{"term":"Prozentwert $W$","explanation":"Der Anteil vom Ganzen."},{"term":"Prozentsatz $p\\,\\%$","explanation":"Der Anteil in Prozent."},{"term":"Grundgleichung","explanation":"","math":"W = G \\cdot \\frac{p}{100}"}]'::jsonb, '{"problem":"Wie viel sind $25\\,\\%$ von $80$ €?","steps":[{"text":"Grundwert $G = 80$, Prozentsatz $25\\,\\% = 0{,}25$."},{"text":"Rechnen:","math":"W = 80 \\cdot 0{,}25 = 20"}],"result":"$25\\,\\%$ von $80$ € sind $20$ €."}'::jsonb, '["$1\\,\\% = \\frac{1}{100} = 0{,}01$","Grundwert = Ganzes, Prozentwert = Teil, Prozentsatz = Anteil in %."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
