insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('prozent-satz-grundwert', 'prozentrechnung', 3, 'Prozentsatz und Grundwert berechnen', 'Rückwärts rechnen: Wie viel Prozent? Wie groß war das Ganze?', 'Du berechnest Prozentsatz und Grundwert und löst Aufgaben mit Rabatten rückwärts.', 'Manchmal kennst du den Teil und das Ganze und suchst den Anteil – oder du kennst den Teil und den Anteil und suchst das Ganze.', '[{"term":"Prozentsatz","explanation":"","math":"p\\,\\% = \\frac{W}{G}"},{"term":"Grundwert","explanation":"","math":"G = \\frac{W}{p\\,\\%}"},{"term":"Verminderter Grundwert","explanation":"Nach $p\\,\\%$ Rabatt bleiben $(100 - p)\\,\\%$ übrig."}]'::jsonb, '{"problem":"Du hast $18$ von $24$ Punkten. Wie viel Prozent sind das?","steps":[{"text":"Anteil berechnen:","math":"\\frac{18}{24} = 0{,}75 = 75\\,\\%"}],"result":"$75\\,\\%$"}'::jsonb, '["$p\\,\\% = W : G$","$G = W : p\\,\\%$","Rabatt rückwärts: durch den verbleibenden Anteil teilen."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
