insert into public.topics (id, curriculum_id, subject, grade, area, title, description, keywords, review_status, position) values ('pythagoras', 'de-gym-mathe-7-9-v1', 'Mathematik', 8, 'Geometrie', 'Satz des Pythagoras', 'Seitenlängen in rechtwinkligen Dreiecken berechnen, prüfen und in Sachaufgaben anwenden.', array['satz des pythagoras', 'pythagoras', 'hypotenuse', 'kathete', 'katheten', 'rechtwinkliges dreieck', 'rechtwinklig', 'a2+b2=c2', 'a^2+b^2=c^2', 'diagonale', 'raumdiagonale']::text[], 'internal-review', 1) on conflict (id) do update set curriculum_id = excluded.curriculum_id, subject = excluded.subject, grade = excluded.grade, area = excluded.area, title = excluded.title, description = excluded.description, keywords = excluded.keywords, review_status = excluded.review_status, position = excluded.position;
insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-grundlagen', 'pythagoras', 1, 'Grundlagen und Definition', 'Katheten, Hypotenuse und die Aussage des Satzes kennenlernen.', 'Du kennst den Satz des Pythagoras und kannst ihn für ein rechtwinkliges Dreieck mit den richtigen Seitenbezeichnungen aufschreiben.', 'In einem rechtwinkligen Dreieck hängen die drei Seitenlängen auf besondere Weise zusammen. Wenn du zwei Seiten kennst, kannst du die dritte berechnen. Dafür musst du zuerst wissen, welche Seite welche Rolle spielt.', '[{"term":"Rechtwinkliges Dreieck","explanation":"Ein Dreieck mit einem Winkel von genau $90^\\circ$."},{"term":"Katheten","explanation":"Die beiden Seiten, die den rechten Winkel einschließen."},{"term":"Hypotenuse","explanation":"Die Seite gegenüber dem rechten Winkel. Sie ist immer die längste Seite."},{"term":"Satz des Pythagoras","explanation":"Sind $a$ und $b$ die Katheten und $c$ die Hypotenuse, dann gilt:","math":"a^2 + b^2 = c^2"}]'::jsonb, '{"problem":"Ein rechtwinkliges Dreieck hat die Katheten $a = 3$ und $b = 4$. Prüfe, dass $c = 5$ die Hypotenuse sein kann.","steps":[{"text":"Der rechte Winkel liegt zwischen $a$ und $b$, also ist $c$ die Hypotenuse."},{"text":"Quadrate der Katheten addieren:","math":"3^2 + 4^2 = 9 + 16 = 25"},{"text":"Quadrat der Hypotenuse:","math":"5^2 = 25"},{"text":"Beide Seiten sind gleich, der Satz ist erfüllt."}],"result":"$3^2 + 4^2 = 5^2$, also passt $c = 5$."}'::jsonb, '["Katheten bilden den rechten Winkel, die Hypotenuse liegt ihm gegenüber.","Die Hypotenuse ist die längste Seite.","Es gilt $a^2 + b^2 = c^2$, wenn $c$ die Hypotenuse ist."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
