insert into public.exercises (id, subtopic_id, position, type, difficulty, prompt, choices, answer, objectives, common_mistakes, figure) values ('pyth-grundlagen-2', 'pyth-grundlagen', 1, 'multiple-choice', 1, 'Im Dreieck $ABC$ liegt der rechte Winkel bei $C$. Welche Gleichung ist richtig?', '[{"id":"a","label":"$a^2 + b^2 = c^2$"},{"id":"b","label":"$a^2 + c^2 = b^2$"},{"id":"c","label":"$a + b = c$"},{"id":"d","label":"$b^2 + c^2 = a^2$"}]'::jsonb, '{"kind":"choice","correct":"a"}'::jsonb, array['Satz des Pythagoras mit Seitenbezeichnungen aufstellen']::text[], '[{"description":"Seiten ohne Quadrate addiert","feedback":"Im Satz werden die Quadrate der Seiten addiert, nicht die Seiten selbst.","answers":["c"]},{"description":"Falsche Seite als Hypotenuse gewählt","feedback":"Die Hypotenuse liegt dem rechten Winkel gegenüber.","answers":["b","d"]}]'::jsonb, null) on conflict (id) do update set subtopic_id = excluded.subtopic_id, position = excluded.position, type = excluded.type, difficulty = excluded.difficulty, prompt = excluded.prompt, choices = excluded.choices, answer = excluded.answer, objectives = excluded.objectives, common_mistakes = excluded.common_mistakes, figure = excluded.figure;
