insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-erkennen', 'pythagoras', 2, 'Rechtwinklige Dreiecke erkennen', 'Rechte Winkel finden – auch in gedrehten oder anders beschrifteten Dreiecken.', 'Du erkennst rechtwinklige Dreiecke über die Winkel und benennst Katheten und Hypotenuse auch in gedrehten Figuren.', 'Bevor du den Satz des Pythagoras anwendest, musst du sicher sein, dass ein rechter Winkel vorhanden ist und wo er liegt. Die Lage oder Drehung des Dreiecks spielt dabei keine Rolle.', '[{"term":"Winkelsumme","explanation":"In jedem Dreieck ergeben die drei Innenwinkel zusammen $180^\\circ$.","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"term":"Dritter Winkel","explanation":"Kennst du zwei Winkel, erhältst du den dritten durch $180^\\circ$ minus deren Summe."},{"term":"Lage egal","explanation":"Ein Dreieck bleibt rechtwinklig, egal wie es gedreht ist. Die Hypotenuse liegt immer dem rechten Winkel gegenüber."}]'::jsonb, '{"problem":"In einem Dreieck $ABC$ gilt $\\alpha = 35^\\circ$ und $\\beta = 55^\\circ$. Ist es rechtwinklig?","steps":[{"text":"Dritten Winkel berechnen:","math":"\\gamma = 180^\\circ - 35^\\circ - 55^\\circ = 90^\\circ"},{"text":"Der rechte Winkel liegt bei $C$, also ist $c$ die Hypotenuse."}],"result":"Ja, das Dreieck ist rechtwinklig mit rechtem Winkel bei $C$."}'::jsonb, '["Die Winkelsumme im Dreieck beträgt $180^\\circ$.","Die Hypotenuse liegt immer gegenüber dem rechten Winkel – unabhängig von der Lage."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
