insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-herleitung', 'pythagoras', 3, 'Herleitung des Satzes', 'Warum der Satz gilt: Flächen von Quadraten und der Ergänzungsbeweis.', 'Du kannst den Satz des Pythagoras mit Quadratflächen deuten und den Ergänzungsbeweis nachvollziehen.', 'Der Satz des Pythagoras ist eigentlich eine Aussage über Flächen: Zeichnet man über jede Seite ein Quadrat, dann sind die beiden kleinen Quadrate zusammen genauso groß wie das große Quadrat.', '[{"term":"Quadratfläche","explanation":"Ein Quadrat mit Seitenlänge $s$ hat den Flächeninhalt","math":"A = s^2"},{"term":"Flächenaussage","explanation":"Die Kathetenquadrate haben zusammen denselben Flächeninhalt wie das Hypotenusenquadrat."},{"term":"Ergänzungsbeweis","explanation":"Ein Quadrat mit Seite $a+b$ enthält vier gleiche rechtwinklige Dreiecke und ein inneres Quadrat mit Seite $c$:","math":"(a+b)^2 = 4 \\cdot \\tfrac{a \\cdot b}{2} + c^2 \\;\\Rightarrow\\; a^2 + b^2 = c^2"}]'::jsonb, '{"problem":"Katheten $a = 3$, $b = 4$. Vergleiche die Quadratflächen.","steps":[{"text":"Quadrat über $a$:","math":"3^2 = 9"},{"text":"Quadrat über $b$:","math":"4^2 = 16"},{"text":"Zusammen:","math":"9 + 16 = 25 = 5^2"}],"result":"Das Quadrat über der Hypotenuse $c = 5$ hat genau $25$ Flächeneinheiten."}'::jsonb, '["$a^2$, $b^2$, $c^2$ sind Flächeninhalte von Quadraten über den Seiten.","Der Ergänzungsbeweis zeigt die Gleichung durch Zerlegen eines großen Quadrats."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
