insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-hypotenuse', 'pythagoras', 4, 'Hypotenuse berechnen', 'Aus zwei Katheten die längste Seite bestimmen.', 'Du berechnest die Hypotenuse aus zwei gegebenen Katheten und rundest sinnvoll.', 'Kennst du beide Katheten, kannst du die Hypotenuse in drei Schritten berechnen: quadrieren, addieren, Wurzel ziehen.', '[{"term":"Formel","explanation":"Für die Hypotenuse gilt:","math":"c = \\sqrt{a^2 + b^2}"},{"term":"Reihenfolge","explanation":"Erst quadrieren, dann addieren, zum Schluss die Wurzel ziehen."},{"term":"Achtung","explanation":"Die Wurzel einer Summe ist nicht die Summe der Wurzeln:","math":"\\sqrt{a^2 + b^2} \\neq a + b"}]'::jsonb, '{"problem":"Berechne $c$ für $a = 5$ cm und $b = 12$ cm.","steps":[{"text":"Quadrieren:","math":"5^2 = 25,\\quad 12^2 = 144"},{"text":"Addieren:","math":"c^2 = 25 + 144 = 169"},{"text":"Wurzel ziehen:","math":"c = \\sqrt{169} = 13"}],"result":"$c = 13$ cm"}'::jsonb, '["$c = \\sqrt{a^2 + b^2}$","Ergebnis plausibel? Die Hypotenuse muss länger als jede Kathete sein."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
