insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-kathete', 'pythagoras', 5, 'Kathete berechnen', 'Eine fehlende Kathete aus Hypotenuse und anderer Kathete bestimmen.', 'Du stellst den Satz nach einer Kathete um und berechnest sie.', 'Ist die Hypotenuse bekannt, wird nicht addiert, sondern subtrahiert. Wichtig: Die Hypotenuse steht immer allein.', '[{"term":"Umgestellt nach $a$","explanation":"","math":"a = \\sqrt{c^2 - b^2}"},{"term":"Umgestellt nach $b$","explanation":"","math":"b = \\sqrt{c^2 - a^2}"},{"term":"Kontrolle","explanation":"Die Kathete muss kürzer als die Hypotenuse sein."}]'::jsonb, '{"problem":"Gegeben: $c = 10$ cm, $a = 6$ cm. Berechne $b$.","steps":[{"text":"Umstellen:","math":"b^2 = c^2 - a^2"},{"text":"Einsetzen:","math":"b^2 = 100 - 36 = 64"},{"text":"Wurzel:","math":"b = 8"}],"result":"$b = 8$ cm"}'::jsonb, '["Kathete: $\\sqrt{c^2 - \\text{andere Kathete}^2}$","Die Kathete ist immer kürzer als die Hypotenuse."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
