insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-umkehrung', 'pythagoras', 6, 'Umkehrung des Satzes', 'Mit drei Seitenlängen prüfen, ob ein Dreieck rechtwinklig ist.', 'Du prüfst mit der Umkehrung des Satzes, ob ein Dreieck mit gegebenen Seiten rechtwinklig ist.', 'Der Satz funktioniert auch rückwärts: Erfüllen die Seiten die Gleichung, dann muss das Dreieck einen rechten Winkel haben.', '[{"term":"Umkehrung","explanation":"Gilt für die längste Seite $c$ die Gleichung $a^2 + b^2 = c^2$, dann ist das Dreieck rechtwinklig. Der rechte Winkel liegt gegenüber von $c$."},{"term":"Längste Seite","explanation":"Setze immer die längste Seite als $c$ ein."},{"term":"Pythagoreische Tripel","explanation":"Ganzzahlige Lösungen, z. B. $(3, 4, 5)$, $(5, 12, 13)$, $(8, 15, 17)$."}]'::jsonb, '{"problem":"Ist ein Dreieck mit den Seiten $7$, $24$ und $25$ rechtwinklig?","steps":[{"text":"Längste Seite: $c = 25$."},{"text":"Prüfen:","math":"7^2 + 24^2 = 49 + 576 = 625"},{"text":"Vergleich:","math":"25^2 = 625"}],"result":"Ja, das Dreieck ist rechtwinklig."}'::jsonb, '["Längste Seite als $c$ wählen.","$a^2 + b^2 = c^2$ ⇒ rechtwinklig; sonst nicht."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
