insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-anwendung', 'pythagoras', 7, 'Anwendungs- und Textaufgaben', 'Leitern, Bildschirme, Drachen: den Satz im Alltag anwenden.', 'Du findest in Sachsituationen rechtwinklige Dreiecke und löst die Aufgabe mit einem Antwortsatz.', 'Viele Alltagsfragen verstecken ein rechtwinkliges Dreieck. Eine Skizze hilft dir, es zu finden.', '[{"term":"Schritt 1","explanation":"Skizze zeichnen und das rechtwinklige Dreieck markieren."},{"term":"Schritt 2","explanation":"Gegebene und gesuchte Seiten eintragen. Ist die gesuchte Seite Hypotenuse oder Kathete?"},{"term":"Schritt 3","explanation":"Rechnen, Einheit beachten, Antwortsatz schreiben."}]'::jsonb, '{"problem":"Eine $5$ m lange Leiter steht $1{,}4$ m von einer Wand entfernt. Wie hoch reicht sie?","steps":[{"text":"Leiter = Hypotenuse $c = 5$, Abstand zur Wand = Kathete $a = 1{,}4$."},{"text":"Höhe gesucht (Kathete):","math":"h = \\sqrt{5^2 - 1{,}4^2} = \\sqrt{25 - 1{,}96} = \\sqrt{23{,}04}"},{"text":"Ergebnis:","math":"h = 4{,}8"}],"result":"Die Leiter reicht $4{,}8$ m hoch."}'::jsonb, '["Erst skizzieren, dann rechnen.","Prüfe, ob die gesuchte Seite Hypotenuse oder Kathete ist.","Antwortsatz mit Einheit."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
