insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('pyth-gemischt', 'pythagoras', 8, 'Gemischte Übungen und Prüfungsvorbereitung', 'Alle Aufgabentypen gemischt – wie in der Klassenarbeit.', 'Du wählst selbstständig den passenden Ansatz und löst auch mehrschrittige Aufgaben.', 'Hier kommt alles zusammen. Überlege bei jeder Aufgabe zuerst: Wo ist das rechtwinklige Dreieck, und was ist gesucht?', '[{"term":"Quadratdiagonale","explanation":"Für ein Quadrat mit Seite $s$ gilt:","math":"d = s\\sqrt{2}"},{"term":"Höhe im gleichseitigen Dreieck","explanation":"Für die Seitenlänge $s$ gilt:","math":"h = \\sqrt{s^2 - \\left(\\tfrac{s}{2}\\right)^2}"},{"term":"Raumdiagonale","explanation":"Im Quader mit Kanten $a$, $b$, $c$:","math":"d = \\sqrt{a^2 + b^2 + c^2}"}]'::jsonb, '{"problem":"Wie lang ist die Raumdiagonale eines Würfels mit Kantenlänge $2$ cm?","steps":[{"text":"Flächendiagonale:","math":"e = \\sqrt{2^2 + 2^2} = \\sqrt{8}"},{"text":"Raumdiagonale:","math":"d = \\sqrt{e^2 + 2^2} = \\sqrt{8 + 4} = \\sqrt{12} \\approx 3{,}46"}],"result":"$d \\approx 3{,}46$ cm"}'::jsonb, '["Rechtwinklige Dreiecke auch in Quadraten, Rechtecken und Körpern suchen.","Mehrschrittige Aufgaben in Teilschritte zerlegen."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
