insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('quad-reinquadratisch', 'quadratische-gleichungen', 1, 'Reinquadratische Gleichungen', 'Gleichungen der Form $x^2 = d$ durch Wurzelziehen lösen.', 'Du löst Gleichungen der Form $x^2 = d$ und gibst alle Lösungen an.', 'Wenn in einer Gleichung nur $x^2$ und Zahlen vorkommen, kannst du nach $x^2$ auflösen und dann die Wurzel ziehen – aber Vorsicht: Es gibt oft zwei Lösungen.', '[{"term":"Zwei Lösungen","explanation":"Für $d > 0$:","math":"x^2 = d \\;\\Rightarrow\\; x = \\sqrt{d} \\text{ oder } x = -\\sqrt{d}"},{"term":"Eine Lösung","explanation":"Für $d = 0$ ist $x = 0$."},{"term":"Keine Lösung","explanation":"Für $d < 0$ gibt es keine reelle Lösung."}]'::jsonb, '{"problem":"Löse $2x^2 - 18 = 0$.","steps":[{"text":"$+18$:","math":"2x^2 = 18"},{"text":"$:2$:","math":"x^2 = 9"},{"text":"Wurzel ziehen:","math":"x_1 = 3,\\; x_2 = -3"}],"result":"$L = \\{-3;\\, 3\\}$"}'::jsonb, '["Nach $x^2$ auflösen, dann $\\pm$ Wurzel.","Negative rechte Seite ⇒ keine Lösung."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
