insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('quad-nullprodukt', 'quadratische-gleichungen', 2, 'Satz vom Nullprodukt', 'Gleichungen durch Ausklammern und Faktorisieren lösen.', 'Du löst quadratische Gleichungen mit dem Satz vom Nullprodukt, auch nach dem Ausklammern.', 'Ein Produkt ist genau dann null, wenn mindestens ein Faktor null ist. Dieser einfache Gedanke hilft beim Lösen vieler Gleichungen.', '[{"term":"Satz vom Nullprodukt","explanation":"","math":"a \\cdot b = 0 \\;\\Leftrightarrow\\; a = 0 \\text{ oder } b = 0"},{"term":"Ausklammern","explanation":"Fehlt das Absolutglied, klammere $x$ aus:","math":"x^2 + px = x(x + p) = 0"},{"term":"Achtung","explanation":"Nie durch $x$ teilen – dabei geht die Lösung $x = 0$ verloren."}]'::jsonb, '{"problem":"Löse $x^2 - 5x = 0$.","steps":[{"text":"Ausklammern:","math":"x(x - 5) = 0"},{"text":"Nullprodukt:","math":"x = 0 \\text{ oder } x - 5 = 0"}],"result":"$L = \\{0;\\, 5\\}$"}'::jsonb, '["Produkt $= 0$ ⇒ ein Faktor $= 0$.","Ausklammern statt durch $x$ teilen."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
