insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values ('quad-pq-formel', 'quadratische-gleichungen', 3, 'pq-Formel', 'Allgemeine quadratische Gleichungen in Normalform lösen.', 'Du bringst Gleichungen in Normalform, wendest die pq-Formel an und bestimmst die Anzahl der Lösungen mit der Diskriminante.', 'Mit der pq-Formel lässt sich jede quadratische Gleichung in Normalform lösen. Die Diskriminante verrät vorher, wie viele Lösungen es gibt.', '[{"term":"Normalform","explanation":"","math":"x^2 + px + q = 0"},{"term":"pq-Formel","explanation":"","math":"x_{1,2} = -\\frac{p}{2} \\pm \\sqrt{\\left(\\frac{p}{2}\\right)^2 - q}"},{"term":"Diskriminante","explanation":"$D = \\left(\\frac{p}{2}\\right)^2 - q$: $D > 0$ zwei, $D = 0$ eine, $D < 0$ keine Lösung."},{"term":"Vorher","explanation":"Steht vor $x^2$ eine Zahl $a \\neq 1$, teile zuerst die ganze Gleichung durch $a$."}]'::jsonb, '{"problem":"Löse $x^2 - 6x + 8 = 0$.","steps":[{"text":"Ablesen: $p = -6$, $q = 8$."},{"text":"Einsetzen:","math":"x_{1,2} = 3 \\pm \\sqrt{9 - 8} = 3 \\pm 1"},{"text":"Lösungen:","math":"x_1 = 4,\\; x_2 = 2"}],"result":"$L = \\{2;\\, 4\\}$"}'::jsonb, '["Normalform herstellen.","$p$ und $q$ mit Vorzeichen ablesen.","Diskriminante entscheidet über die Anzahl der Lösungen."]'::jsonb) on conflict (id) do update set topic_id = excluded.topic_id, position = excluded.position, title = excluded.title, description = excluded.description, objective = excluded.objective, intro = excluded.intro, rules = excluded.rules, example = excluded.example, summary = excluded.summary;
